        available: autoContextWindow != null,
        unavailable_reason: autoContextWindow != null ? null : 'no_models',
      },
      ...claudeFamilyEntries,
      ...profileRows.map(p => ({
        id: `auto:${p.name.toLowerCase()}`,
        object: 'model',
        created: 0,
        owned_by: 'freellmapi',
        name: `Auto: ${p.name} (named fallback chain)`,
        context_window: p.max_ctx,
        context_length: p.max_ctx,
