  // happening now, so it belongs to this minute and to today.
  const inFlight = provisionalRequests(platform, modelId, keyId, now);

  if (limits.rpm !== null) {
    if (requestCount(platform, modelId, keyId, MINUTE, now) + inFlight >= limits.rpm) return false;
