import { describe, it, expect, beforeEach } from 'vitest';
import { acquireLease, canUseKeyConcurrency, inFlightForKey, resetLeases } from '../../services/ratelimit';

describe('Cross-key concurrency stacking', () => {
  beforeEach(() => {
    resetLeases();
    delete process.env.MAX_CONCURRENT_REQUESTS_PER_KEY_HUGGINGFACE;
  });

  it('stacks concurrency independently across different keys of the same platform', () => {
    const platform = 'huggingface';
    const keyId1 = 101;
    const keyId2 = 102;

    // Default built-in limit for huggingface is 4
    expect(canUseKeyConcurrency(platform, keyId1)).toBe(true);
    expect(canUseKeyConcurrency(platform, keyId2)).toBe(true);

    // Fill key 1 up to its concurrency limit (4 requests)
    acquireLease(platform, 'Qwen/Qwen3.5', keyId1, 100);
    acquireLease(platform, 'Qwen/Qwen3.5', keyId1, 100);
    acquireLease(platform, 'Qwen/Qwen3.5', keyId1, 100);
    acquireLease(platform, 'Qwen/Qwen3.5', keyId1, 100);

    expect(inFlightForKey(platform, keyId1)).toBe(4);
    expect(canUseKeyConcurrency(platform, keyId1)).toBe(false);

    // Key 2 should still have full capacity available (stacking independently)
    expect(inFlightForKey(platform, keyId2)).toBe(0);
    expect(canUseKeyConcurrency(platform, keyId2)).toBe(true);

    acquireLease(platform, 'Qwen/Qwen3.5', keyId2, 100);
    expect(inFlightForKey(platform, keyId2)).toBe(1);
    expect(canUseKeyConcurrency(platform, keyId2)).toBe(true);
  });
});
